  function createGuWorm(guId, overrides = {}) {
    const tpl = GU_CATALOG[guId] ?? GU_CATALOG.nguyet_quang;
    return {
      ...tpl,
      uid: overrides.uid ?? `gu_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`,
      hunger: overrides.hunger ?? 100,
      // 0..100, dưới 20 đói, 0 suy kiệt
      mastery: overrides.mastery ?? 0,
      star: overrides.star ?? 1,
      isWild: Boolean(overrides.isWild)
    };
  }

