            this._advanceQuest("awaken_aperture", {});
            this.sfx?.play("fusionSuccess");
            this.spawnVfx("vfx/nguyet-quang", g.x, g.y, { scale: 0.9 });
            this.onAwakenCeremony?.({ type: "awakened", ...res });
            this.onStateChange?.(this);
            return true;
